export const PRESET_AGENTS: PresetAgent[] = RAW_MKAI_PRESETS.map((item) => ({
  id: item.id,
  name: item.name,
  nameEn: item.nameEn,
  icon: encodeAgentAvatarIcon({
    svg: (AgentAvatarSvg as Record<string, AgentAvatarSvg>)[item.iconSvg] || AgentAvatarSvg.Brain,
  }),
  description: item.description,
  descriptionEn: item.descriptionEn,
  identity: item.identity,
  identityEn: item.identityEn,
  systemPrompt: item.systemPrompt,
  systemPromptEn: item.systemPromptEn,
  skillIds: item.skillIds,
  model: item.model,
  modelTier: item.modelTier as 'fast' | 'main' | 'heavy',
  subagentAllowAgentIds: item.subagentAllowAgentIds,
}));

export function presetToCreateRequest(preset: PresetAgent): CreateAgentRequest {
  const isEn = getLanguage() === 'en';
  return {
    id: preset.id,
    name: isEn && preset.nameEn ? preset.nameEn : preset.name,
    description: isEn && preset.descriptionEn ? preset.descriptionEn : preset.description,
    identity: isEn && preset.identityEn ? preset.identityEn : preset.identity,
    systemPrompt: isEn && preset.systemPromptEn ? preset.systemPromptEn : preset.systemPrompt,
    icon: preset.icon,
    skillIds: preset.skillIds,
    model: preset.model || 'custom_0/gpt-oss-120b',
    subagentAllowAgentIds: preset.subagentAllowAgentIds || [],
    source: 'preset',
    presetId: preset.id,
  };
}
